pub mod ipc;
pub mod terminal;
pub mod worktree;

use ipc::*;
use std::sync::Arc;
use terminal::PtyManager;
use worktree::WorkspaceRegistry;

pub fn create_app<R: tauri::Runtime>(builder: tauri::Builder<R>) -> tauri::Builder<R> {
    let pty_manager = Arc::new(PtyManager::new());
    let workspace_registry = WorkspaceRegistry::new();

    if let Ok(repo_root) = std::env::current_dir() {
        if let Err(error) = workspace_registry.register("default", &repo_root) {
            tracing::debug!(
                "Current directory is not a registrable Orca workspace ({}): {}",
                repo_root.display(),
                error
            );
        }
    }

    builder
        .manage(pty_manager)
        .manage(workspace_registry)
        .invoke_handler(tauri::generate_handler![
            cmd_terminal_spawn,
            cmd_terminal_write,
            cmd_terminal_resize,
            cmd_terminal_signal,
            cmd_terminal_close,
            cmd_terminal_list,
            cmd_worktree_list,
            cmd_worktree_create,
            cmd_worktree_delete,
            cmd_worktree_delete_destructive,
            cmd_worktree_delete_preview,
            cmd_worktree_status,
        ])
}

#[cfg_attr(mobile, tauri::mobile_entry_point)]
pub fn run() {
    create_app(tauri::Builder::default())
        .run(tauri::generate_context!())
        .expect("error while running tauri application");
}

#![cfg_attr(not(debug_assertions), windows_subsystem = "windows")]

fn main() {
    orca_lite_lib::run();
}

import { FolderPlus, GitBranch, Plus, X } from "lucide-react";
import { useCallback, useMemo, useState } from "react";

import { Sidebar } from "./components/Sidebar";
import { TabBar } from "./components/TabBar";
import { TerminalSplitView } from "./components/TerminalSplitView";
import { WorkspaceHeader } from "./components/WorkspaceHeader";
import { worktreeErrorMessage } from "./lib/ipcErrors";
import { createWorktree, DEFAULT_WORKSPACE_ID, toIpcError } from "./lib/tauri";
import { worktreeIdentity, type Worktree } from "./lib/types";
import { useWorkspaceRuntime } from "./state/workspaceRuntime";
import { useWorkspaceStore } from "./state/workspaceStore";

export function App() {
  const {
    state,
    agents,
    openTab,
    ensureTabForWorktree,
    closeTab,
    enableSplit,
    rotateSplit,
    disableSplit,
    activatePrimary,
    syncWorktrees,
  } = useWorkspaceStore();
  const { runtimeError, refreshWorktrees, reportRuntimeError } = useWorkspaceRuntime({
    activeWorktreePath: state.activeWorktreePath,
    syncWorktrees,
    ensureTabForWorktree,
  });
  const [isCreateOpen, setIsCreateOpen] = useState(false);
  const [newSlug, setNewSlug] = useState("");
  const [newBaseRef, setNewBaseRef] = useState("HEAD");
  const [createError, setCreateError] = useState<string | null>(null);

  const activeWorktree = useMemo(
    () => state.worktrees.find((worktree) => worktree.path === state.activeWorktreePath) ?? null,
    [state.activeWorktreePath, state.worktrees],
  );
  const activeAgent = agents.find((agent) => agent.worktreePath === activeWorktree?.path);

  const handleSelectWorktree = useCallback(
    (worktree: Worktree) => {
      void ensureTabForWorktree(worktree).catch(reportRuntimeError);
    },
    [ensureTabForWorktree, reportRuntimeError],
  );

  const handleCreateWorktreeSubmit = async (event: React.FormEvent) => {
    event.preventDefault();
    const slug = newSlug.trim();
    if (!slug || !activeWorktree) return;

    try {
      setCreateError(null);
      await createWorktree({
        workspaceId: DEFAULT_WORKSPACE_ID,
        worktree: { wsId: worktreeIdentity(activeWorktree)?.wsId ?? DEFAULT_WORKSPACE_ID, slug },
        baseRef: newBaseRef || null,
      });
      setIsCreateOpen(false);
      setNewSlug("");
      await refreshWorktrees();
    } catch (error) {
      setCreateError(worktreeErrorMessage(toIpcError(error)));
    }
  };

  const handleAddTerminalTab = () => {
    if (!activeWorktree) return;
    void openTab(activeWorktree).catch(reportRuntimeError);
  };

  const handleCloseTab = (tabId: string) => {
    void closeTab(tabId).catch(reportRuntimeError);
  };

  const handleSplit = () => {
    if (state.layout.split === "none") {
      void enableSplit("horizontal").catch(reportRuntimeError);
    } else if (state.layout.split === "horizontal") {
      rotateSplit();
    } else {
      disableSplit();
    }
  };

  return (
    <div className="flex h-screen w-screen select-none overflow-hidden bg-background font-sans text-foreground">
      <Sidebar
        worktrees={state.worktrees}
        agents={agents}
        activePath={activeWorktree?.path || ""}
        onSelectWorktree={handleSelectWorktree}
        onCreateWorktree={() => {
          setCreateError(null);
          setIsCreateOpen(true);
        }}
      />

      <main className="flex h-full flex-1 flex-col overflow-hidden bg-card">
        {activeWorktree ? (
          <>
            <WorkspaceHeader
              worktree={activeWorktree}
              agent={activeAgent}
              onSplit={handleSplit}
              splitState={state.layout.split}
            />
            <TabBar
              tabs={state.layout.tabs}
              activeTabId={state.layout.primaryTabId ?? ""}
              onActivate={activatePrimary}
              onClose={handleCloseTab}
              onAdd={handleAddTerminalTab}
            />
            <TerminalSplitView layout={state.layout} sessions={state.sessions} />
          </>
        ) : (
          <div className="flex h-full flex-1 items-center justify-center text-xs text-muted-foreground">
            {runtimeError ? `Workspace unavailable (${runtimeError.code})` : "No workspace available"}
          </div>
        )}
      </main>

      {runtimeError && activeWorktree ? (
        <div className="pointer-events-none fixed bottom-3 right-3 z-40 max-w-error rounded-md border border-destructive/30 bg-card/95 px-3 py-2 text-[11px] text-destructive shadow-lg">
          {runtimeError.code}: {runtimeError.message}
        </div>
      ) : null}

      {isCreateOpen ? (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm">
          <form
            onSubmit={handleCreateWorktreeSubmit}
            className="w-96 animate-enter space-y-4 rounded-xl border border-border bg-card p-5 shadow-2xl"
          >
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-2 text-sm font-semibold">
                <FolderPlus className="size-4 text-primary" />
                <span>Create New Worktree</span>
              </div>
              <button
                type="button"
                onClick={() => setIsCreateOpen(false)}
                className="text-muted-foreground hover:text-foreground"
              >
                <X className="size-4" />
              </button>
            </div>

            <div className="space-y-3 text-xs">
              <div>
                <label className="mb-1 block text-muted-foreground">Branch / Worktree Slug</label>
                <input
                  type="text"
                  autoFocus
                  placeholder="e.g. feature-auth"
                  value={newSlug}
                  onChange={(event) => setNewSlug(event.target.value)}
                  className="w-full rounded-md border border-input bg-background px-3 py-1.5 text-xs text-foreground focus:outline-none focus:ring-1 focus:ring-primary"
                />
              </div>

              <div>
                <label className="mb-1 block text-muted-foreground">Base Ref / Branch</label>
                <div className="flex items-center gap-2 rounded-md border border-input bg-background px-3 py-1.5 text-xs text-foreground">
                  <GitBranch className="size-3.5 text-muted-foreground" />
                  <input
                    type="text"
                    value={newBaseRef}
                    onChange={(event) => setNewBaseRef(event.target.value)}
                    className="flex-1 bg-transparent focus:outline-none"
                  />
                </div>
              </div>
              {createError ? <p className="rounded-md bg-destructive/10 px-2 py-1.5 text-destructive">{createError}</p> : null}
            </div>

            <div className="flex justify-end gap-2 pt-2">
              <button
                type="button"
                onClick={() => setIsCreateOpen(false)}
                className="rounded-md px-3 py-1.5 text-xs text-muted-foreground hover:bg-accent hover:text-foreground"
              >
                Cancel
              </button>
              <button
                type="submit"
                className="flex items-center gap-1.5 rounded-md bg-primary px-3.5 py-1.5 text-xs font-medium text-primary-foreground transition-colors hover:bg-primary/90"
              >
                <Plus className="size-3.5" />
                <span>Create Worktree</span>
              </button>
            </div>
          </form>
        </div>
      ) : null}
    </div>
  );
}

export default App;

import { useCallback, useEffect, useReducer, useRef } from "react";

import { closeTerminal, DEFAULT_WORKSPACE_ID, spawnTerminal } from "../lib/tauri";
import { ensureTerminalEvents, terminalEventBus } from "../lib/terminalEvents";
import { worktreeIdentity } from "../lib/types";
import type {
  ActiveAgent,
  LayoutState,
  SplitMode,
  TerminalLifecycle,
  TerminalLifecyclePayload,
  TerminalSession,
  TerminalTab,
  Worktree,
  WorktreeIdentity,
} from "../lib/types";
import { createLayoutState, layoutReducer } from "./layout";

export type WorkspaceState = {
  worktrees: Worktree[];
  activeWorktreePath: string | null;
  sessions: Record<string, TerminalSession>;
  layout: LayoutState;
};

export type WorkspaceServices = {
  ensureTerminalEvents: () => Promise<void>;
  spawnTerminal: (request: { workspaceId: string; worktree: WorktreeIdentity | null }) => Promise<string>;
  closeTerminal: (sessionId: string) => Promise<void>;
};

type WorkspaceAction =
  | { type: "SET_WORKTREES"; worktrees: Worktree[] }
  | { type: "SELECT_WORKTREE"; path: string }
  | { type: "ADD_TAB_WITH_SESSION"; tab: TerminalTab; session: TerminalSession }
  | {
      type: "ENABLE_SPLIT_WITH_SESSION";
      tab: TerminalTab;
      session: TerminalSession;
      orientation: Exclude<SplitMode, "none">;
    }
  | { type: "ENABLE_SPLIT_EXISTING"; tabId: string; orientation: Exclude<SplitMode, "none"> }
  | {
      type: "CLOSE_TAB";
      tabId: string;
      replacement?: { tab: TerminalTab; session: TerminalSession };
    }
  | { type: "ACTIVATE_PRIMARY"; tabId: string }
  | { type: "ACTIVATE_SECONDARY"; tabId: string }
  | { type: "ROTATE_SPLIT" }
  | { type: "DISABLE_SPLIT" }
  | { type: "SESSION_LIFECYCLE"; backendSessionId: string; lifecycle: TerminalLifecycle };

type UseWorkspaceStoreOptions = {
  initialWorktrees?: Worktree[];
  services?: WorkspaceServices;
};

const defaultServices: WorkspaceServices = {
  ensureTerminalEvents,
  spawnTerminal,
  closeTerminal,
};

export function useWorkspaceStore({ initialWorktrees = [], services = defaultServices }: UseWorkspaceStoreOptions = {}) {
  const [state, reactDispatch] = useReducer(workspaceReducer, initialWorktrees, createInitialState);
  const stateRef = useRef(state);
  stateRef.current = state;

  const dispatch = useCallback((action: WorkspaceAction) => {
    stateRef.current = workspaceReducer(stateRef.current, action);
    reactDispatch(action);
  }, []);

  useEffect(
    () =>
      terminalEventBus.subscribeLifecycle((payload) => {
        dispatch({
          type: "SESSION_LIFECYCLE",
          backendSessionId: payload.sessionId,
          lifecycle: mapBackendLifecycle(payload),
        });
      }),
    [dispatch],
  );

  const createSpawnedTab = useCallback(
    async (worktree: Worktree, label?: string) => {
      await services.ensureTerminalEvents();
      const backendSessionId = await services.spawnTerminal({
        workspaceId: DEFAULT_WORKSPACE_ID,
        worktree: worktreeIdentity(worktree),
      });
      const sessionId = createId("session");
      const tabId = createId("tab");
      const session: TerminalSession = {
        id: sessionId,
        cwd: worktree.path,
        workspaceId: DEFAULT_WORKSPACE_ID,
        worktree: worktreeIdentity(worktree),
        backendSessionId,
        lifecycle: "working",
      };
      const tab: TerminalTab = {
        id: tabId,
        label: label ?? nextTabLabel(worktree, stateRef.current.layout.tabs, stateRef.current.sessions),
        sessionId,
      };
      return { tab, session };
    },
    [services],
  );

  const openTab = useCallback(
    async (worktree: Worktree) => {
      const binding = await createSpawnedTab(worktree);
      dispatch({ type: "ADD_TAB_WITH_SESSION", ...binding });
      if (!stateRef.current.worktrees.some((candidate) => candidate.path === worktree.path)) {
        dispatch({ type: "SET_WORKTREES", worktrees: [...stateRef.current.worktrees, worktree] });
      }
      dispatch({ type: "SELECT_WORKTREE", path: worktree.path });
      return binding.tab.id;
    },
    [createSpawnedTab, dispatch],
  );

  const ensureTabForWorktree = useCallback(
    async (worktree: Worktree) => {
      const snapshot = stateRef.current;
      const existing = snapshot.layout.tabs.find((tab) => snapshot.sessions[tab.sessionId]?.cwd === worktree.path);
      dispatch({ type: "SELECT_WORKTREE", path: worktree.path });
      if (existing) {
        dispatch({ type: "ACTIVATE_PRIMARY", tabId: existing.id });
        return existing.id;
      }
      return openTab(worktree);
    },
    [dispatch, openTab],
  );

  const enableSplit = useCallback(
    async (orientation: Exclude<SplitMode, "none"> = "horizontal") => {
      let snapshot = stateRef.current;
      if (!snapshot.layout.primaryTabId) {
        const activeWorktree = getActiveWorktree(snapshot);
        if (!activeWorktree) return;
        await openTab(activeWorktree);
        snapshot = stateRef.current;
      }

      const primaryTabId = snapshot.layout.primaryTabId;
      const existingSecondary = snapshot.layout.tabs.find((tab) => tab.id !== primaryTabId);
      if (existingSecondary) {
        dispatch({ type: "ENABLE_SPLIT_EXISTING", tabId: existingSecondary.id, orientation });
        return;
      }

      const primaryTab = snapshot.layout.tabs.find((tab) => tab.id === primaryTabId);
      const primarySession = primaryTab ? snapshot.sessions[primaryTab.sessionId] : undefined;
      const activeWorktree =
        (primarySession && snapshot.worktrees.find((worktree) => worktree.path === primarySession.cwd)) ??
        getActiveWorktree(snapshot);
      if (!activeWorktree) return;

      const binding = await createSpawnedTab(activeWorktree);
      dispatch({ type: "ENABLE_SPLIT_WITH_SESSION", ...binding, orientation });
    },
    [createSpawnedTab, dispatch, openTab],
  );

  const closeTab = useCallback(
    async (tabId: string) => {
      const snapshot = stateRef.current;
      const closingTab = snapshot.layout.tabs.find((tab) => tab.id === tabId);
      if (!closingTab) return;
      const closingSession = snapshot.sessions[closingTab.sessionId];

      let replacement: { tab: TerminalTab; session: TerminalSession } | undefined;
      if (snapshot.layout.tabs.length === 1) {
        const worktree =
          (closingSession && snapshot.worktrees.find((candidate) => candidate.path === closingSession.cwd)) ??
          getActiveWorktree(snapshot);
        if (!worktree) return;
        replacement = await createSpawnedTab(worktree, closingTab.label);
      }

      dispatch({ type: "CLOSE_TAB", tabId, replacement });
      await closeBackendSession(closingSession, services);
    },
    [createSpawnedTab, dispatch, services],
  );

  const syncWorktrees = useCallback(
    async (worktrees: Worktree[]) => {
      const snapshot = stateRef.current;
      const validWorktreePaths = new Set(worktrees.map((worktree) => worktree.path));
      const staleSessions = Object.values(snapshot.sessions).filter((session) => !validWorktreePaths.has(session.cwd));
      dispatch({ type: "SET_WORKTREES", worktrees });
      await Promise.allSettled(staleSessions.map((session) => closeBackendSession(session, services)));
    },
    [dispatch, services],
  );

  const rotateSplit = useCallback(() => dispatch({ type: "ROTATE_SPLIT" }), [dispatch]);
  const disableSplit = useCallback(() => dispatch({ type: "DISABLE_SPLIT" }), [dispatch]);
  const activatePrimary = useCallback((tabId: string) => dispatch({ type: "ACTIVATE_PRIMARY", tabId }), [dispatch]);
  const activateSecondary = useCallback((tabId: string) => dispatch({ type: "ACTIVATE_SECONDARY", tabId }), [dispatch]);

  return {
    state,
    agents: selectAgents(state),
    openTab,
    ensureTabForWorktree,
    closeTab,
    enableSplit,
    rotateSplit,
    disableSplit,
    activatePrimary,
    activateSecondary,
    syncWorktrees,
  };
}

export function selectAgents(state: WorkspaceState): ActiveAgent[] {
  return state.layout.tabs.flatMap((tab) => {
    const session = state.sessions[tab.sessionId];
    if (!session) return [];
    const worktree = state.worktrees.find((candidate) => candidate.path === session.cwd);
    return [
      {
        id: session.backendSessionId ?? session.id,
        name: tab.label,
        task: worktree?.branch?.replace(/^refs\/heads\//, "") ?? session.cwd,
        state: session.lifecycle,
        worktree: session.worktree,
        worktreePath: worktree?.path ?? session.cwd,
        sessionId: session.backendSessionId ?? session.id,
      },
    ];
  });
}

function createInitialState(worktrees: Worktree[]): WorkspaceState {
  return {
    worktrees,
    activeWorktreePath: worktrees[0]?.path ?? null,
    sessions: {},
    layout: createLayoutState(),
  };
}

function workspaceReducer(state: WorkspaceState, action: WorkspaceAction): WorkspaceState {
  switch (action.type) {
    case "SET_WORKTREES": {
      const validWorktreePaths = new Set(action.worktrees.map((worktree) => worktree.path));
      const sessions = Object.fromEntries(
        Object.entries(state.sessions).filter(([, session]) => validWorktreePaths.has(session.cwd)),
      );
      let layout = state.layout;
      for (const tab of state.layout.tabs) {
        if (!sessions[tab.sessionId]) layout = layoutReducer(layout, { type: "CLOSE_TAB", tabId: tab.id });
      }
      const activeWorktreePath = action.worktrees.some((worktree) => worktree.path === state.activeWorktreePath)
        ? state.activeWorktreePath
        : action.worktrees[0]?.path ?? null;
      return { ...state, worktrees: action.worktrees, activeWorktreePath, sessions, layout };
    }
    case "SELECT_WORKTREE":
      return state.worktrees.some((worktree) => worktree.path === action.path)
        ? { ...state, activeWorktreePath: action.path }
        : state;
    case "ADD_TAB_WITH_SESSION":
      return {
        ...state,
        sessions: { ...state.sessions, [action.session.id]: action.session },
        layout: layoutReducer(state.layout, { type: "ADD_TAB", tab: action.tab }),
      };
    case "ENABLE_SPLIT_WITH_SESSION":
      return {
        ...state,
        sessions: { ...state.sessions, [action.session.id]: action.session },
        layout: layoutReducer(state.layout, {
          type: "ENABLE_SPLIT",
          orientation: action.orientation,
          secondaryTab: action.tab,
        }),
      };
    case "ENABLE_SPLIT_EXISTING":
      return {
        ...state,
        layout: layoutReducer(state.layout, {
          type: "ENABLE_SPLIT",
          orientation: action.orientation,
          secondaryTabId: action.tabId,
        }),
      };
    case "CLOSE_TAB": {
      const closingTab = state.layout.tabs.find((tab) => tab.id === action.tabId);
      const sessions = { ...state.sessions };
      if (closingTab) delete sessions[closingTab.sessionId];
      if (action.replacement) sessions[action.replacement.session.id] = action.replacement.session;
      return {
        ...state,
        sessions,
        layout: layoutReducer(state.layout, {
          type: "CLOSE_TAB",
          tabId: action.tabId,
          replacementTab: action.replacement?.tab,
        }),
      };
    }
    case "ACTIVATE_PRIMARY":
      return { ...state, layout: layoutReducer(state.layout, { type: "ACTIVATE_PRIMARY", tabId: action.tabId }) };
    case "ACTIVATE_SECONDARY":
      return { ...state, layout: layoutReducer(state.layout, { type: "ACTIVATE_SECONDARY", tabId: action.tabId }) };
    case "ROTATE_SPLIT":
      return { ...state, layout: layoutReducer(state.layout, { type: "ROTATE_SPLIT" }) };
    case "DISABLE_SPLIT":
      return { ...state, layout: layoutReducer(state.layout, { type: "DISABLE_SPLIT" }) };
    case "SESSION_LIFECYCLE": {
      const sessions = Object.fromEntries(
        Object.entries(state.sessions).map(([id, session]) => [
          id,
          session.backendSessionId === action.backendSessionId ? { ...session, lifecycle: action.lifecycle } : session,
        ]),
      );
      return { ...state, sessions };
    }
  }
}

async function closeBackendSession(session: TerminalSession | undefined, services: WorkspaceServices) {
  if (!session?.backendSessionId) return;
  try {
    await services.closeTerminal(session.backendSessionId);
  } finally {
    terminalEventBus.clearSession(session.backendSessionId);
  }
}

function getActiveWorktree(state: WorkspaceState) {
  return state.worktrees.find((worktree) => worktree.path === state.activeWorktreePath) ?? state.worktrees[0] ?? null;
}

function nextTabLabel(worktree: Worktree, tabs: TerminalTab[], sessions: Record<string, TerminalSession>) {
  const base = worktree.path === "." ? "main" : worktree.path.split(/[\\/]/).filter(Boolean).at(-1) ?? worktree.path;
  const count = tabs.filter((tab) => sessions[tab.sessionId]?.cwd === worktree.path).length + 1;
  return count === 1 ? base : `${base} (${count})`;
}

function mapBackendLifecycle(payload: TerminalLifecyclePayload): TerminalLifecycle {
  if (payload.state === "started") return "working";
  if (payload.state === "failed") return "failed";
  return "exited";
}

function createId(prefix: string) {
  const randomPart = globalThis.crypto?.randomUUID?.() ?? `${Date.now()}-${Math.random().toString(36).slice(2)}`;
  return `${prefix}:${randomPart}`;
}

import { useCallback, useEffect, useRef, useState } from "react";

import {
  DEFAULT_WORKSPACE_ID,
  isTauriRuntime,
  listWorktrees,
  onWorktreeChanged,
  toIpcError,
} from "../lib/tauri";
import { ensureTerminalEvents } from "../lib/terminalEvents";
import type { StructuredIpcError, Worktree, WorktreeChangedPayload } from "../lib/types";

export type WorkspaceRuntimeServices = {
  ensureTerminalEvents: () => Promise<void>;
  listWorktrees: (workspaceId: string) => Promise<Worktree[]>;
  onWorktreeChanged: (handler: (payload: WorktreeChangedPayload) => void) => Promise<() => void>;
  isTauriRuntime: () => boolean;
};

type UseWorkspaceRuntimeOptions = {
  activeWorktreePath: string | null;
  syncWorktrees: (worktrees: Worktree[]) => Promise<void>;
  ensureTabForWorktree: (worktree: Worktree) => Promise<string>;
  services?: WorkspaceRuntimeServices;
};

const defaultServices: WorkspaceRuntimeServices = {
  ensureTerminalEvents,
  listWorktrees,
  onWorktreeChanged,
  isTauriRuntime,
};

const PREVIEW_WORKTREE: Worktree = {
  path: ".",
  head: "main",
  branch: "refs/heads/main",
  bare: false,
  detached: false,
  locked: null,
  prunable: null,
};

export function useWorkspaceRuntime({
  activeWorktreePath,
  syncWorktrees,
  ensureTabForWorktree,
  services = defaultServices,
}: UseWorkspaceRuntimeOptions) {
  const [runtimeError, setRuntimeError] = useState<StructuredIpcError | null>(null);
  const activeWorktreePathRef = useRef(activeWorktreePath);
  const refreshInFlightRef = useRef<Promise<void> | null>(null);
  activeWorktreePathRef.current = activeWorktreePath;

  const reportRuntimeError = useCallback((error: unknown) => {
    setRuntimeError(toIpcError(error));
  }, []);

  const refreshWorktrees = useCallback(() => {
    if (refreshInFlightRef.current) return refreshInFlightRef.current;

    const refreshPromise = (async () => {
      try {
        const listed = await services.listWorktrees(DEFAULT_WORKSPACE_ID);
        const worktrees = listed.length > 0 || services.isTauriRuntime() ? listed : [PREVIEW_WORKTREE];
        await syncWorktrees(worktrees);
        const preferred = worktrees.find((worktree) => worktree.path === activeWorktreePathRef.current) ?? worktrees[0];
        if (preferred) await ensureTabForWorktree(preferred);
        setRuntimeError(null);
      } catch (error) {
        reportRuntimeError(error);
      }
    })().finally(() => {
      refreshInFlightRef.current = null;
    });

    refreshInFlightRef.current = refreshPromise;
    return refreshPromise;
  }, [ensureTabForWorktree, reportRuntimeError, services, syncWorktrees]);

  useEffect(() => {
    let disposed = false;
    let unlistenWorktreeChanged: (() => void) | undefined;

    const initialize = async () => {
      await services.ensureTerminalEvents();
      if (disposed) return;
      unlistenWorktreeChanged = await services.onWorktreeChanged(() => {
        void refreshWorktrees();
      });
      if (disposed) {
        unlistenWorktreeChanged();
        return;
      }
      await refreshWorktrees();
    };

    const handleFocus = () => {
      void refreshWorktrees();
    };

    window.addEventListener("focus", handleFocus);
    void initialize().catch(reportRuntimeError);

    return () => {
      disposed = true;
      window.removeEventListener("focus", handleFocus);
      unlistenWorktreeChanged?.();
    };
  }, [refreshWorktrees, reportRuntimeError, services]);

  return { runtimeError, refreshWorktrees, reportRuntimeError };
}

use crate::worktree::{Worktree, WorktreeError, WorktreeIdentity, WorktreeManager};
use parking_lot::RwLock;
use std::collections::HashMap;
use std::path::{Path, PathBuf};
use std::sync::Arc;

#[derive(Debug, Clone, Default)]
pub struct WorkspaceRegistry {
    workspaces: Arc<RwLock<HashMap<String, WorktreeManager>>>,
}

impl WorkspaceRegistry {
    pub fn new() -> Self {
        Self::default()
    }

    fn validate_workspace_id(workspace_id: &str) -> Result<&str, WorktreeError> {
        let workspace_id = workspace_id.trim();
        if workspace_id.is_empty() {
            return Err(WorktreeError::InvalidNamespace {
                reason: "Workspace registry ID cannot be empty".into(),
            });
        }
        if workspace_id.starts_with('-')
            || workspace_id.contains('/')
            || workspace_id.contains('\\')
            || workspace_id.chars().any(|ch| ch.is_control() || ch.is_whitespace())
        {
            return Err(WorktreeError::InvalidNamespace {
                reason: "Workspace registry ID contains unsafe characters".into(),
            });
        }
        Ok(workspace_id)
    }

    pub fn register(
        &self,
        workspace_id: impl AsRef<str>,
        repo_root: impl AsRef<Path>,
    ) -> Result<(), WorktreeError> {
        let workspace_id = Self::validate_workspace_id(workspace_id.as_ref())?.to_string();
        let manager = WorktreeManager::try_new(repo_root.as_ref().to_path_buf())?;
        let mut workspaces = self.workspaces.write();
        if workspaces.contains_key(&workspace_id) {
            return Err(WorktreeError::WorkspaceAlreadyRegistered { workspace_id });
        }
        workspaces.insert(workspace_id, manager);
        Ok(())
    }

    pub fn contains(&self, workspace_id: &str) -> bool {
        self.workspaces.read().contains_key(workspace_id)
    }

    pub fn manager(&self, workspace_id: &str) -> Result<WorktreeManager, WorktreeError> {
        let workspace_id = Self::validate_workspace_id(workspace_id)?;
        self.workspaces
            .read()
            .get(workspace_id)
            .cloned()
            .ok_or_else(|| WorktreeError::WorkspaceNotFound {
                workspace_id: workspace_id.to_string(),
            })
    }

    pub fn repo_root(&self, workspace_id: &str) -> Result<PathBuf, WorktreeError> {
        Ok(self.manager(workspace_id)?.repo_root().to_path_buf())
    }

    pub fn target_path(
        &self,
        workspace_id: &str,
        identity: &WorktreeIdentity,
    ) -> Result<PathBuf, WorktreeError> {
        self.manager(workspace_id)?
            .worktree_path_for(&identity.ws_id, &identity.slug)
    }

    pub fn resolve_worktree(
        &self,
        workspace_id: &str,
        identity: &WorktreeIdentity,
    ) -> Result<(WorktreeManager, Worktree), WorktreeError> {
        let manager = self.manager(workspace_id)?;
        let worktree = manager
            .find_worktree_by_slug(&identity.ws_id, &identity.slug)?
            .ok_or_else(|| WorktreeError::WorktreeIdentityNotFound {
                workspace_id: workspace_id.to_string(),
                ws_id: identity.ws_id.clone(),
                slug: identity.slug.clone(),
            })?;
        manager.canonical_allowed_path(&worktree.path)?;
        Ok((manager, worktree))
    }

    pub fn resolve_terminal_target(
        &self,
        workspace_id: &str,
        identity: Option<&WorktreeIdentity>,
    ) -> Result<(WorktreeManager, PathBuf), WorktreeError> {
        if let Some(identity) = identity {
            let (manager, worktree) = self.resolve_worktree(workspace_id, identity)?;
            let path = manager.canonical_allowed_path(&worktree.path)?;
            return Ok((manager, path));
        }

        let manager = self.manager(workspace_id)?;
        let path = manager.repo_root().to_path_buf();
        Ok((manager, path))
    }
}

use crate::worktree::git::{
    git_branch_delete, git_status_porcelain, git_worktree_add, git_worktree_list,
    git_worktree_prune, git_worktree_remove, run_git,
};
use crate::worktree::model::{
    BranchDeletionPreview, CreateWorktreeOptions, DirtyState, OrcaWorktreeInfo, Worktree,
    WorktreeError,
};
use parking_lot::Mutex;
use std::collections::HashMap;
use std::fs;
use std::path::{Component, Path, PathBuf};
use std::sync::Arc;

const ORCA_WORKTREE_DIR: &str = ".orca-worktrees";

#[derive(Debug, Clone, Default)]
pub struct WriterLeaseRegistry {
    writers: Arc<Mutex<HashMap<PathBuf, String>>>,
}

impl WriterLeaseRegistry {
    fn acquire_canonical(&self, path: PathBuf, owner_id: &str) -> Result<(), WorktreeError> {
        let mut writers = self.writers.lock();
        if let Some(existing_owner) = writers.get(&path) {
            return Err(WorktreeError::WriterAlreadyActive {
                path,
                owner_id: existing_owner.clone(),
            });
        }
        writers.insert(path, owner_id.to_string());
        Ok(())
    }

    fn release_canonical(&self, path: &Path, owner_id: &str) -> Result<(), WorktreeError> {
        let mut writers = self.writers.lock();
        let Some(existing_owner) = writers.get(path) else {
            return Ok(());
        };
        if existing_owner != owner_id {
            return Err(WorktreeError::WriterLeaseOwnerMismatch {
                path: path.to_path_buf(),
                owner_id: existing_owner.clone(),
                requested_owner_id: owner_id.to_string(),
            });
        }
        writers.remove(path);
        Ok(())
    }

    fn owner_canonical(&self, path: &Path) -> Option<String> {
        self.writers.lock().get(path).cloned()
    }
}

#[derive(Debug)]
pub(crate) struct WriterLeaseGuard {
    registry: WriterLeaseRegistry,
    canonical_path: PathBuf,
    owner_id: String,
}

impl WriterLeaseGuard {
    fn new(registry: WriterLeaseRegistry, canonical_path: PathBuf, owner_id: String) -> Self {
        Self {
            registry,
            canonical_path,
            owner_id,
        }
    }

    pub(crate) fn canonical_path(&self) -> &Path {
        &self.canonical_path
    }

    pub(crate) fn owner_id(&self) -> &str {
        &self.owner_id
    }
}

impl Drop for WriterLeaseGuard {
    fn drop(&mut self) {
        let _ = self
            .registry
            .release_canonical(&self.canonical_path, &self.owner_id);
    }
}

/// Manages Git worktrees under a canonical repository root.
///
/// Every filesystem path accepted by this manager must stay inside `repo_root` after
/// canonicalization. IPC callers should prefer identity-based resolution through
/// `WorkspaceRegistry` instead of passing paths directly.
#[derive(Debug, Clone)]
pub struct WorktreeManager {
    repo_root: PathBuf,
    writer_leases: WriterLeaseRegistry,
    delete_lock: Arc<Mutex<()>>,
}

impl WorktreeManager {
    /// Creates a manager and immediately validates/canonicalizes the Git repository root.
    /// Invalid roots are programmer configuration errors; fallible callers should use `try_new`.
    pub fn new(repo_root: impl Into<PathBuf>) -> Self {
        let requested = repo_root.into();
        Self::try_new(&requested)
            .unwrap_or_else(|error| panic!("invalid worktree manager root '{}': {error}", requested.display()))
    }

    pub fn try_new(repo_root: impl Into<PathBuf>) -> Result<Self, WorktreeError> {
        let requested = repo_root.into();
        let canonical = fs::canonicalize(&requested)
            .map_err(|_| WorktreeError::InvalidRepoRoot {
                path: requested.clone(),
            })?;
        if !canonical.is_dir() {
            return Err(WorktreeError::InvalidRepoRoot { path: canonical });
        }

        let top_level = run_git(&canonical, &["rev-parse", "--show-toplevel"])
            .map_err(|_| WorktreeError::InvalidRepoRoot {
                path: canonical.clone(),
            })?;
        let git_root = fs::canonicalize(PathBuf::from(top_level.trim())).map_err(|_| {
            WorktreeError::InvalidRepoRoot {
                path: canonical.clone(),
            }
        })?;
        if git_root != canonical {
            return Err(WorktreeError::InvalidRepoRoot { path: canonical });
        }

        Ok(Self {
            repo_root: git_root,
            writer_leases: WriterLeaseRegistry::default(),
            delete_lock: Arc::new(Mutex::new(())),
        })
    }

    pub fn repo_root(&self) -> &Path {
        &self.repo_root
    }

    fn validate_path_components(&self, path: &Path) -> Result<(), WorktreeError> {
        if !path.is_absolute() {
            return Err(WorktreeError::InvalidPath {
                path: path.to_path_buf(),
                reason: "path must be absolute".into(),
            });
        }
        if path.components().any(|component| matches!(component, Component::ParentDir)) {
            return Err(WorktreeError::InvalidPath {
                path: path.to_path_buf(),
                reason: "parent traversal ('..') is forbidden".into(),
            });
        }
        if let Some(name) = path.file_name().and_then(|name| name.to_str()) {
            if name.starts_with('-') {
                return Err(WorktreeError::InvalidPath {
                    path: path.to_path_buf(),
                    reason: "path component cannot start with a dash".into(),
                });
            }
            if name.chars().any(char::is_control) {
                return Err(WorktreeError::InvalidPath {
                    path: path.to_path_buf(),
                    reason: "path component cannot contain control characters".into(),
                });
            }
        }
        Ok(())
    }

    fn ensure_canonical_inside_root(
        &self,
        original: &Path,
        canonical: PathBuf,
    ) -> Result<PathBuf, WorktreeError> {
        if canonical == self.repo_root || canonical.starts_with(&self.repo_root) {
            Ok(canonical)
        } else {
            Err(WorktreeError::PathOutsideWorkspace {
                path: original.to_path_buf(),
                root: self.repo_root.clone(),
            })
        }
    }

    pub fn canonical_allowed_path(&self, path: &Path) -> Result<PathBuf, WorktreeError> {
        self.validate_path_components(path)?;
        let canonical = fs::canonicalize(path).map_err(|_| WorktreeError::WorktreeNotFound {
            path: path.to_path_buf(),
        })?;
        self.ensure_canonical_inside_root(path, canonical)
    }

    fn validate_new_worktree_path(&self, path: &Path) -> Result<(), WorktreeError> {
        self.validate_path_components(path)?;
        if !path.starts_with(&self.repo_root) {
            return Err(WorktreeError::PathOutsideWorkspace {
                path: path.to_path_buf(),
                root: self.repo_root.clone(),
            });
        }

        let mut ancestor = path.parent().ok_or_else(|| WorktreeError::InvalidPath {
            path: path.to_path_buf(),
            reason: "worktree target has no parent".into(),
        })?;
        while !ancestor.exists() {
            ancestor = ancestor.parent().ok_or_else(|| WorktreeError::InvalidPath {
                path: path.to_path_buf(),
                reason: "worktree target has no existing ancestor".into(),
            })?;
        }
        let canonical_ancestor = fs::canonicalize(ancestor)?;
        self.ensure_canonical_inside_root(path, canonical_ancestor)?;
        Ok(())
    }

    fn canonical_worktree_path(&self, path: &Path) -> Result<PathBuf, WorktreeError> {
        self.canonical_allowed_path(path)
    }

    pub fn worktree_path_for(&self, ws_id: &str, slug: &str) -> Result<PathBuf, WorktreeError> {
        Self::format_branch_name(ws_id, slug)?;
        let mut target = self.repo_root.join(ORCA_WORKTREE_DIR).join(ws_id);
        for segment in slug.split('/') {
            target.push(segment);
        }
        self.validate_new_worktree_path(&target)?;
        Ok(target)
    }

    pub fn acquire_writer(&self, worktree_path: &Path, owner_id: &str) -> Result<(), WorktreeError> {
        let _delete_guard = self.delete_lock.lock();
        let canonical = self.canonical_worktree_path(worktree_path)?;
        self.writer_leases.acquire_canonical(canonical, owner_id)
    }

    pub fn release_writer(&self, worktree_path: &Path, owner_id: &str) -> Result<(), WorktreeError> {
        let canonical = self.canonical_worktree_path(worktree_path)?;
        self.writer_leases.release_canonical(&canonical, owner_id)
    }

    pub fn writer_owner(&self, worktree_path: &Path) -> Result<Option<String>, WorktreeError> {
        let canonical = self.canonical_worktree_path(worktree_path)?;
        Ok(self.writer_leases.owner_canonical(&canonical))
    }

    pub(crate) fn acquire_writer_lease(
        &self,
        worktree_path: &Path,
        owner_id: &str,
    ) -> Result<WriterLeaseGuard, WorktreeError> {
        let _delete_guard = self.delete_lock.lock();
        let canonical = self.canonical_worktree_path(worktree_path)?;
        self.writer_leases
            .acquire_canonical(canonical.clone(), owner_id)?;
        Ok(WriterLeaseGuard::new(
            self.writer_leases.clone(),
            canonical,
            owner_id.to_string(),
        ))
    }

    pub fn format_branch_name(ws_id: &str, slug: &str) -> Result<String, WorktreeError> {
        let ws_id = ws_id.trim();
        let slug = slug.trim();
        if ws_id.is_empty() {
            return Err(WorktreeError::InvalidNamespace {
                reason: "Workspace ID cannot be empty".into(),
            });
        }
        if slug.is_empty() {
            return Err(WorktreeError::InvalidNamespace {
                reason: "Slug cannot be empty".into(),
            });
        }
        if ws_id.contains('/') {
            return Err(WorktreeError::InvalidNamespace {
                reason: "Workspace ID cannot contain '/'".into(),
            });
        }
        Self::validate_ref_component(ws_id, "workspace ID")?;
        Self::validate_ref_component(slug, "slug")?;
        Ok(format!("orca/{ws_id}/{slug}"))
    }

    pub fn parse_branch_name(branch: &str) -> Option<OrcaWorktreeInfo> {
        let short = branch.strip_prefix("refs/heads/").unwrap_or(branch);
        let parts: Vec<&str> = short.split('/').collect();
        if parts.len() >= 3 && parts[0] == "orca" {
            Some(OrcaWorktreeInfo {
                ws_id: parts[1].to_string(),
                slug: parts[2..].join("/"),
            })
        } else {
            None
        }
    }

    fn validate_ref_component(component: &str, label: &str) -> Result<(), WorktreeError> {
        if component.contains("..") || component.contains("//") || component.contains("@{") {
            return Err(WorktreeError::InvalidNamespace {
                reason: format!("{label} cannot contain '..', '//', or '@{{'"),
            });
        }

        for segment in component.split('/') {
            if segment.is_empty()
                || segment.starts_with('.')
                || segment.ends_with('.')
                || segment.starts_with('-')
            {
                return Err(WorktreeError::InvalidNamespace {
                    reason: format!(
                        "{label} path segments cannot be empty or start/end with '.', or start with '-'"
                    ),
                });
            }
            if segment.ends_with(".lock") {
                return Err(WorktreeError::InvalidNamespace {
                    reason: format!("{label} cannot end with '.lock'"),
                });
            }
            for ch in segment.chars() {
                if ch.is_ascii_control()
                    || ch.is_whitespace()
                    || matches!(ch, '~' | '^' | ':' | '?' | '*' | '[' | '\\')
                {
                    return Err(WorktreeError::InvalidNamespace {
                        reason: format!("{label} contains invalid character '{ch}'"),
                    });
                }
            }
        }
        Ok(())
    }

    pub fn create_worktree(
        &self,
        options: CreateWorktreeOptions,
    ) -> Result<Worktree, WorktreeError> {
        let branch_name = Self::format_branch_name(&options.ws_id, &options.slug)?;
        self.validate_new_worktree_path(&options.path)?;
        if options.path.exists() {
            self.canonical_allowed_path(&options.path)?;
            return Err(WorktreeError::WorktreeAlreadyExists { path: options.path });
        }

        let parent = options
            .path
            .parent()
            .ok_or_else(|| WorktreeError::InvalidPath {
                path: options.path.clone(),
                reason: "worktree target has no parent".into(),
            })?;
        fs::create_dir_all(parent)?;
        let canonical_parent = fs::canonicalize(parent)?;
        self.ensure_canonical_inside_root(&options.path, canonical_parent)?;

        git_worktree_add(
            &self.repo_root,
            &options.path,
            &branch_name,
            options.base_ref.as_deref(),
        )?;

        let target_canonical = self.canonical_allowed_path(&options.path)?;
        for wt in self.list_worktrees()? {
            if let Ok(wt_canonical) = self.canonical_allowed_path(&wt.path) {
                if wt_canonical == target_canonical {
                    return Ok(wt);
                }
            }
        }

        Ok(Worktree {
            path: target_canonical,
            head: String::new(),
            branch: Some(format!("refs/heads/{branch_name}")),
            bare: false,
            detached: false,
            locked: None,
            prunable: None,
        })
    }

    pub fn list_worktrees(&self) -> Result<Vec<Worktree>, WorktreeError> {
        let worktrees = git_worktree_list(&self.repo_root)?;
        Ok(worktrees
            .into_iter()
            .filter_map(|mut wt| {
                let canonical = self.canonical_allowed_path(&wt.path).ok()?;
                wt.path = canonical;
                Some(wt)
            })
            .collect())
    }

    pub fn find_worktree(&self, path: &Path) -> Result<Option<Worktree>, WorktreeError> {
        let target_canonical = self.canonical_allowed_path(path)?;
        for wt in self.list_worktrees()? {
            if wt.path == target_canonical {
                return Ok(Some(wt));
            }
        }
        Ok(None)
    }

    pub fn find_worktree_by_slug(
        &self,
        ws_id: &str,
        slug: &str,
    ) -> Result<Option<Worktree>, WorktreeError> {
        let target_branch = Self::format_branch_name(ws_id, slug)?;
        for wt in self.list_worktrees()? {
            if wt.branch_short_name() == Some(target_branch.as_str()) {
                return Ok(Some(wt));
            }
        }
        Ok(None)
    }

    pub fn check_dirty(&self, worktree_path: &Path) -> Result<DirtyState, WorktreeError> {
        let canonical = self.canonical_worktree_path(worktree_path)?;
        git_status_porcelain(&canonical)
    }

    pub fn is_dirty(&self, worktree_path: &Path) -> Result<bool, WorktreeError> {
        self.check_dirty(worktree_path).map(|state| state.is_dirty)
    }

    fn ensure_no_writer(&self, worktree_path: &Path) -> Result<(), WorktreeError> {
        let canonical = self.canonical_worktree_path(worktree_path)?;
        if let Some(owner_id) = self.writer_leases.owner_canonical(&canonical) {
            return Err(WorktreeError::WriterAlreadyActive {
                path: canonical,
                owner_id,
            });
        }
        Ok(())
    }

    fn remove_worktree_locked(
        &self,
        worktree_path: &Path,
        force: bool,
    ) -> Result<(), WorktreeError> {
        let canonical = self.canonical_worktree_path(worktree_path)?;
        self.ensure_no_writer(&canonical)?;
        let dirty_state = self.check_dirty(&canonical)?;
        if dirty_state.is_dirty {
            let count = dirty_state.files.len();
            let files = dirty_state.files.into_iter().map(|file| file.path).collect();
            return Err(WorktreeError::DirtyWorktree {
                path: canonical,
                count,
                files,
            });
        }

        git_worktree_remove(&self.repo_root, &canonical, force)?;
        let _ = git_worktree_prune(&self.repo_root);
        Ok(())
    }

    pub fn remove_worktree(&self, worktree_path: &Path, force: bool) -> Result<(), WorktreeError> {
        let _delete_guard = self.delete_lock.lock();
        self.remove_worktree_locked(worktree_path, force)
    }

    pub fn safe_delete(&self, worktree_path: &Path) -> Result<(), WorktreeError> {
        self.remove_worktree(worktree_path, false)
    }

    fn branch_is_merged(&self, branch: &str) -> Result<bool, WorktreeError> {
        let merged = run_git(
            &self.repo_root,
            &["branch", "--merged", "HEAD", "--format=%(refname:short)"],
        )?;
        Ok(merged.lines().any(|line| line.trim() == branch))
    }

    pub fn branch_deletion_preview(
        &self,
        worktree_path: &Path,
    ) -> Result<BranchDeletionPreview, WorktreeError> {
        let canonical = self.canonical_worktree_path(worktree_path)?;
        let existing = self
            .find_worktree(&canonical)?
            .ok_or_else(|| WorktreeError::WorktreeNotFound {
                path: canonical.clone(),
            })?;
        let branch = existing
            .branch_short_name()
            .ok_or_else(|| WorktreeError::ParseError("Detached worktree has no branch".into()))?
            .to_string();
        let head = if existing.head.is_empty() {
            run_git(&self.repo_root, &["rev-parse", "--verify", &branch])?
                .trim()
                .to_string()
        } else {
            existing.head
        };
        let merged = self.branch_is_merged(&branch)?;
        let upstream = run_git(
            &self.repo_root,
            &["rev-parse", "--abbrev-ref", &format!("{branch}@{{upstream}}")],
        )
        .ok()
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty());

        let (ahead, behind) = if let Some(upstream_ref) = upstream.as_deref() {
            let counts = run_git(
                &self.repo_root,
                &[
                    "rev-list",
                    "--left-right",
                    "--count",
                    &format!("{upstream_ref}...{branch}"),
                ],
            )?;
            let mut values = counts.split_whitespace();
            let behind = values.next().and_then(|value| value.parse::<u64>().ok());
            let ahead = values.next().and_then(|value| value.parse::<u64>().ok());
            (ahead, behind)
        } else {
            (None, None)
        };

        Ok(BranchDeletionPreview {
            branch,
            head,
            upstream,
            merged,
            ahead,
            behind,
        })
    }

    pub fn delete_worktree_and_branch(
        &self,
        worktree_path: &Path,
        delete_branch: bool,
    ) -> Result<(), WorktreeError> {
        let _delete_guard = self.delete_lock.lock();
        self.ensure_no_writer(worktree_path)?;

        let branch_preview = if delete_branch {
            let preview = self.branch_deletion_preview(worktree_path)?;
            if !preview.merged {
                return Err(WorktreeError::UnmergedBranch {
                    branch: preview.branch,
                    head: preview.head,
                });
            }
            Some(preview)
        } else {
            None
        };

        self.remove_worktree_locked(worktree_path, false)?;
        if let Some(preview) = branch_preview {
            git_branch_delete(&self.repo_root, &preview.branch, false)?;
        }
        Ok(())
    }

    pub fn delete_worktree_and_branch_destructive(
        &self,
        worktree_path: &Path,
        delete_branch: bool,
    ) -> Result<(), WorktreeError> {
        let _delete_guard = self.delete_lock.lock();
        self.ensure_no_writer(worktree_path)?;
        let branch = if delete_branch {
            Some(self.branch_deletion_preview(worktree_path)?.branch)
        } else {
            None
        };

        self.remove_worktree_locked(worktree_path, false)?;
        if let Some(branch) = branch {
            git_branch_delete(&self.repo_root, &branch, true)?;
        }
        Ok(())
    }
}

